import java.lang.reflect.*;

public class ReflectionBasicsDemo {
    static class Employee {
        private final String name;
        private double salary;

        public Employee(String name, double salary) {
            this.name = name;
            this.salary = salary;
        }

        public double getSalary() { return salary; }
        public void raiseSalary(double amount) { this.salary += amount; }
    }

    public static void main(String[] args) throws Exception {
        // Trzy sposoby zdobycia Class
        Class<Employee> c1 = Employee.class;
        Employee e = new Employee("Anna", 5000.0);
        Class<?> c2 = e.getClass();
        Class<?> c3 = Class.forName(c1.getName());
        System.out.println(c1 == c2 && c2 == c3); // true

        // getDeclaredFields - wszystkie pola, niezaleznie od widocznosci
        for (Field f : Employee.class.getDeclaredFields()) {
            System.out.println(f.getName());
        }

        // Method.invoke
        Method getSalary = Employee.class.getMethod("getSalary");
        System.out.println(getSalary.invoke(e)); // 5000.0

        Method raise = Employee.class.getMethod("raiseSalary", double.class);
        raise.invoke(e, 300.0);
        System.out.println(e.getSalary()); // 5300.0

        // Constructor.newInstance
        Constructor<Employee> ctor = Employee.class.getConstructor(String.class, double.class);
        Employee e2 = ctor.newInstance("Jan", 4000.0);

        // setAccessible + Field.get/set na prywatnym polu
        Field nameField = Employee.class.getDeclaredField("name");
        nameField.setAccessible(true);
        System.out.println(nameField.get(e2)); // Jan
    }
}
