static void injectByType(Object target, Object dependency) throws Exception {
    for (Field f : target.getClass().getDeclaredFields()) {
        if (f.getType().isAssignableFrom(dependency.getClass())) {
            f.setAccessible(true);
            f.set(target, dependency);
        }
    }
}

