static void categorizeFields(Class<?> type) {
    int prim = 0, ref = 0;
    for (Field f : type.getDeclaredFields()) {
        if (f.getType().isPrimitive()) prim++;
        else ref++;
    }
    System.out.println("prymitywne: " + prim + ", referencyjne: " + ref);
}

