static Object invokeChain(Object start, String... methodNames) {
    Object current = start;
    for (String name : methodNames) {
        try {
            Method m = current.getClass().getMethod(name);
            current = m.invoke(current);
        } catch (Exception e) {
            System.out.println("Blad przy wywolaniu '" + name + "': " + e.getMessage());
            return null;
        }
    }
    return current;
}

System.out.println(invokeChain("  ala  ", "trim", "toUpperCase")); // ALA

@SuppressWarnings("unchecked")
static <T> T shallowCopy(T source) throws Exception {
    Class<T> type = (Class<T>) source.getClass();
    Constructor<T> ctor = type.getDeclaredConstructor();
    ctor.setAccessible(true);
    T copy = ctor.newInstance();
    for (Field f : type.getDeclaredFields()) {
        f.setAccessible(true);
        f.set(copy, f.get(source));
    }
    return copy;
}

