System.out.println(validate(invalid)); // [name nie moze byc puste]

Employee e = new Employee();
Method getSalary = Employee.class.getMethod("getSalary");

long startDirect = System.nanoTime();
for (int i = 0; i < 1_000_000; i++) e.getSalary();
long directTime = System.nanoTime() - startDirect;

long startReflective = System.nanoTime();
for (int i = 0; i < 1_000_000; i++) getSalary.invoke(e);
long reflectiveTime = System.nanoTime() - startReflective;

System.out.println("Bezposrednio: " + directTime + " ns");
System.out.println("Reflekcyjnie: " + reflectiveTime + " ns");
System.out.println("Stosunek: " + ((double) reflectiveTime / directTime));
// Wywolanie reflekcyjne jest zazwyczaj WOLNIEJSZE niz bezposrednie - narzut sprawdzania dostepu/typow przy kazdym invoke().

static void inspect(Object obj) throws Exception {
    Class<?> type = obj.getClass();
    System.out.println("Klasa: " + type.getName());

    System.out.println("Pola:");
    for (Field f : type.getDeclaredFields()) {
        f.setAccessible(true);
        System.out.println("  " + f.getName() + " : " + f.getType().getSimpleName()
                + " [" + Modifier.toString(f.getModifiers()) + "] = " + f.get(obj));
    }

    System.out.println("Metody:");
    for (Method m : type.getDeclaredMethods()) {
        System.out.println("  " + m.getName() + "(" + java.util.Arrays.toString(m.getParameterTypes())
                + ") -> " + m.getReturnType().getSimpleName());
    }

    System.out.println("Konstruktory:");
    for (Constructor<?> c : type.getDeclaredConstructors()) {
        System.out.println("  parametrow: " + c.getParameterCount()
                + " [" + Modifier.toString(c.getModifiers()) + "]");
    }
}

